//! Official NIST ACVP (FIPS 203) Known Answer Tests (KAT) for ML-KEM-768 and ML-KEM-1024.
//! Source: usnistgov/ACVP-Server gen-val/json-files/ML-KEM-encapDecap-FIPS203/internalProjection.json

use quantacipher_core::KemAlgorithm;

#[test]
fn test_nist_acvp_mlkem768_decapsulation() {
    // ACVP Test Group 2, Test Case 26
    let dk_hex = "";
    let c_hex = "";
    let expected_k_hex = "79d74f6c6c2d916bec47bd828fd9b67295a37f54927fab1263c0d122f1c6f1ed";

    let dk_bytes = hex::decode(dk_hex).expect("Valid dk hex");
    let c_bytes = hex::decode(c_hex).expect("Valid c hex");

    assert_eq!(dk_bytes.len(), KemAlgorithm::MlKem768.private_key_len());
    assert_eq!(c_bytes.len(), KemAlgorithm::MlKem768.ciphertext_len());

    let shared_secret = KemAlgorithm::MlKem768
        .decapsulate(&dk_bytes, &c_bytes)
        .expect("Decapsulation must succeed on official NIST ACVP vector");

    let shared_secret_hex = hex::encode(shared_secret.as_slice());
    assert_eq!(shared_secret_hex, expected_k_hex, "Decapsulated key must match NIST ACVP vector");
}

#[test]
