    // ACVP Test Group 3, Test Case 51
    let dk_hex = "";
    let c_hex = "";
    let expected_k_hex = "5087e3b0c90bf601dd6501e071270eff8683621e9f5d67a7a668e50c4f460a75";

    let dk_bytes = hex::decode(dk_hex).expect("Valid dk hex");
